contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address a, address b) public {
        require(a != b);
        c.setOwner(a); if (__ESBMC_reverted()) return;
        c.setOwner(b); if (__ESBMC_reverted()) return;
        c.setOwner(a); if (__ESBMC_reverted()) return;
        address current = c.owner(); if (__ESBMC_reverted()) return;
        assert(current == a);
    }

    receive() external payable {}
}

