contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Owned c;

    function setUp() public {
        c = new Owned();
    }

    function _run(address a, address b) internal {
        vm.assume(a != b);
        try c.setOwner(a) {} catch { return; }
        try c.setOwner(b) {} catch { return; }
        try c.setOwner(a) {} catch { return; }
        address current;
        try c.owner() returns (address __r) { current = __r; } catch { return; }
        assertTrue(current == a);
    }

    function testFuzz_run(address a, address b) public {
